# Generated by Cursor (plan: invalid question mark sequence fix)
"""Scan for replacement char + ? (e.g. \ufffd?) and replace with single ?."""

import re

REPLACEMENT_CHAR = "\ufffd"
INVALID_QUESTION_MARK_RE = re.compile(re.escape(REPLACEMENT_CHAR) + r"\s*\?")


def scan_turn_invalid_question_mark(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (invalid_question_mark_fix, start_index, span, path_str) for \ufffd? matches."""
    result: list[tuple[str, int, str, str]] = []
    for m in INVALID_QUESTION_MARK_RE.finditer(text):
        result.append(("invalid_question_mark_fix", m.start(), m.group(0), path_str))
    return result
